import random
import struct
from typing import List

# This generator targets arbitrary binary data consumers in the provided fuzz stubs.
# Strategy:
# - Produce seeded, repeatable byte strings with varied lengths tailored to the stubs:
#   * Small buffers (1..1024) suitable for DEV_SPI_Write_nByte and Paint bitmaps
#   * Medium/region-sized buffers (up to ~2KB) suitable for partial display paths
#   * Pattern-rich content (repeating tiles, ramps, bit patterns) to exercise rendering paths
# - Keep size <= 4096 bytes overall as required.
# - Content is valid arbitrary binary data (no structure required), but includes common patterns
#   that exercise code paths expecting different grayscale/packing behavior when re-used by stubs.

MAX_TOTAL = 4096

# Some useful deterministic pattern builders

def pattern_repeat(seed: bytes, length: int) -> bytes:
    if not seed:
        seed = b"\x00"
    reps, rem = divmod(length, len(seed))
    return seed * reps + seed[:rem]

def pattern_ramp(length: int, start: int = 0, step: int = 1) -> bytes:
    return bytes(((start + i * step) & 0xFF) for i in range(length))

def pattern_bitwalk(length: int) -> bytes:
    # bytes with single bit walking: 01,02,04,08,10,20,40,80,01,...
    vals = [1,2,4,8,16,32,64,128]
    out = bytearray(length)
    for i in range(length):
        out[i] = vals[i % len(vals)]
    return bytes(out)

def pattern_checker(length: int, a: int = 0xAA, b: int = 0x55) -> bytes:
    return bytes((a if (i & 1) == 0 else b) & 0xFF for i in range(length))


def choose_lengths(rng: random.Random) -> List[int]:
    # Construct a list of segment lengths that sum to <= MAX_TOTAL, with emphasis on sizes
    # useful to consumers: 1..1024 for SPI, up to ~2048 for partial updates.
    lengths: List[int] = []
    remaining = MAX_TOTAL

    # Prioritize at least one segment sized for common upper bounds
    candidates = [
        rng.randint(1, 64),              # tiny
        rng.randint(65, 256),            # small
        rng.randint(257, 1024),          # SPI max
        rng.randint(128, 2048),          # partial display cap in some stubs
    ]
    rng.shuffle(candidates)
    for c in candidates:
        if c <= remaining:
            lengths.append(c)
            remaining -= c
    # Optionally add one more small tail segment
    if remaining > 0 and rng.random() < 0.6:
        tail = rng.randint(1, min(remaining, 256))
        lengths.append(tail)
        remaining -= tail

    return lengths


def build_segment(rng: random.Random, length: int, base_seed: bytes) -> bytes:
    # Mix multiple patterns to create richer content while remaining valid arbitrary bytes
    choice = rng.randint(0, 6)
    if choice == 0:
        # Raw repeat of seed
        return pattern_repeat(base_seed, length)
    elif choice == 1:
        # Ramp with random start/step
        start = rng.randint(0, 255)
        step = rng.choice([1, 2, 3, 5, 7, 11, 13, 17])
        return pattern_ramp(length, start, step)
    elif choice == 2:
        # Bit-walking pattern
        return pattern_bitwalk(length)
    elif choice == 3:
        # Checkerboard AA/55 or random pair
        a = rng.randint(0, 255)
        b = rng.randint(0, 255)
        return pattern_checker(length, a, b)
    elif choice == 4:
        # Tiles: repeat first N bytes of seed with tile size chosen
        tile_sizes = [1, 2, 4, 8, 16, 32, 64]
        tile = base_seed[:rng.choice(tile_sizes)] or bytes([rng.randint(0, 255)])
        return pattern_repeat(tile, length)
    elif choice == 5:
        # Interleave two patterns
        half = (length + 1) // 2
        p1 = pattern_ramp(half, rng.randint(0, 255), rng.choice([1, 3, 5]))
        p2 = pattern_repeat(base_seed[::-1], length - half)
        return (p1 + p2)[:length]
    else:
        # Random but seeded PRNG bytes
        return bytes(rng.getrandbits(8) for _ in range(length))


def make_seed_bytes(rng: random.Random) -> bytes:
    # Create a base seed buffer (1..256 bytes) mixing numeric seed and simple patterns
    n = rng.randint(1, 256)
    # Embed the numeric seed value in little-endian form to vary content even if other patterns repeat
    seed_val = rng.getrandbits(32)
    header = struct.pack('<I', seed_val)
    body = bytes(rng.getrandbits(8) for _ in range(max(1, n - len(header))))
    seed = (header + body)[:n]
    # Ensure non-empty
    if not seed:
        seed = b"\x00"
    return seed


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    base_seed = make_seed_bytes(rng)
    lengths = choose_lengths(rng)

    segments: List[bytes] = []
    for L in lengths:
        seg = build_segment(rng, L, base_seed)
        segments.append(seg)

    data = b"".join(segments)
    # Ensure non-empty and within limit
    if not data:
        data = bytes([0])
    if len(data) > MAX_TOTAL:
        data = data[:MAX_TOTAL]
    return data

import io
import random
import struct
from typing import List, Tuple

# Generator for valid BMP files with common uncompressed formats.
# Avoid recursion; ensure output <= 4096 bytes deterministically by bounding dims.

BI_RGB = 0

def _pad4(n: int) -> int:
    return (4 - (n % 4)) % 4

def _make_palette_gray(ncolors: int) -> bytes:
    if ncolors <= 1:
        steps = [0]
    else:
        steps = [round(i * 255 / (ncolors - 1)) for i in range(ncolors)]
    out = bytearray()
    for v in steps:
        out += bytes([v, v, v, 0])
    return bytes(out)

def _make_palette_colorful(ncolors: int, rng: random.Random) -> bytes:
    base = [
        (0, 0, 0), (255, 255, 255), (255, 0, 0), (0, 255, 0), (0, 0, 255),
        (255, 255, 0), (0, 255, 255), (255, 0, 255), (128, 128, 128), (64, 64, 64)
    ]
    entries = list(base[:min(len(base), ncolors)])
    while len(entries) < ncolors:
        entries.append((rng.randrange(256), rng.randrange(256), rng.randrange(256)))
    out = bytearray()
    for r, g, b in entries[:ncolors]:
        out += bytes([b, g, r, 0])
    return bytes(out)

def _row_packed_1bpp(width: int, rng: random.Random) -> bytes:
    nbits = width
    nbytes = (nbits + 7) // 8
    data = bytearray(rng.getrandbits(8) for _ in range(nbytes))
    unused = (nbytes * 8) - nbits
    if unused:
        data[-1] &= (0xFF << unused) & 0xFF
    return bytes(data)

def _row_packed_nbpp(width: int, bpp: int, rng: random.Random) -> bytes:
    pixels = [rng.randrange(1 << bpp) for _ in range(width)]
    out = bytearray()
    if bpp == 4:
        for i in range(0, width, 2):
            hi = pixels[i]
            lo = pixels[i+1] if i + 1 < width else 0
            out.append(((hi & 0xF) << 4) | (lo & 0xF))
    elif bpp == 2:
        for i in range(0, width, 4):
            p0 = pixels[i]
            p1 = pixels[i+1] if i+1 < width else 0
            p2 = pixels[i+2] if i+2 < width else 0
            p3 = pixels[i+3] if i+3 < width else 0
            out.append(((p0 & 3) << 6) | ((p1 & 3) << 4) | ((p2 & 3) << 2) | (p3 & 3))
    else:
        raise ValueError("Unsupported packed bpp")
    return bytes(out)

def _row_8bpp(width: int, rng: random.Random) -> bytes:
    return bytes(rng.randrange(256) for _ in range(width))

def _row_16bpp_rgb565(width: int, rng: random.Random) -> bytes:
    out = bytearray()
    for _ in range(width):
        r5 = rng.randrange(32)
        g6 = rng.randrange(64)
        b5 = rng.randrange(32)
        val = (r5 << 11) | (g6 << 5) | b5
        out += struct.pack('<H', val)
    return bytes(out)

def _row_24bpp(width: int, rng: random.Random) -> bytes:
    out = bytearray()
    for _ in range(width):
        out += bytes([rng.randrange(256), rng.randrange(256), rng.randrange(256)])
    return bytes(out)

def _row_32bpp_xrgb(width: int, rng: random.Random) -> bytes:
    out = bytearray()
    for _ in range(width):
        out += bytes([rng.randrange(256), rng.randrange(256), rng.randrange(256), 0])
    return bytes(out)

def _choose_dims(rng: random.Random, bpp: int) -> Tuple[int, int]:
    # Choose dims that keep total size comfortably under 4096 for worst-case (32bpp)
    # We'll tailor heights for each bpp considering headers (~54 bytes + palette)
    # Predefined safe sizes
    size_options = {
        1:  [(64,64), (80,80), (96,96), (128,64)],
        2:  [(64,64), (96,64), (96,96), (128,64)],
        4:  [(64,64), (96,64), (96,96), (128,64)],
        8:  [(64,64), (80,80), (96,64), (96,96)],
        16: [(64,64), (80,60), (96,48), (128,32)],
        24: [(48,48), (64,48), (64,64), (80,40)],
        32: [(40,40), (48,32), (56,28), (64,24)],
    }
    return rng.choice(size_options[bpp])

def _estimate_size(width: int, height: int, bpp: int, ncolors: int) -> int:
    raw_stride = {
        1: (width + 7) // 8,
        2: (width + 3) // 4,
        4: (width + 1) // 2,
        8: width,
        16: width * 2,
        24: width * 3,
        32: width * 4,
    }[bpp]
    stride = raw_stride + _pad4(raw_stride)
    palette = ncolors * 4 if (bpp <= 8) else 0
    return 14 + 40 + palette + stride * abs(height)

def _build_bmp(seed: int) -> bytes:
    rng = random.Random(seed)

    bpp_options = [1, 2, 4, 8, 16, 24, 32]
    bpp = rng.choice(bpp_options)

    width, height_abs = _choose_dims(rng, bpp)
    # Top-down sometimes
    top_down = rng.random() < 0.3
    height = -height_abs if top_down else height_abs

    biSize = 40
    planes = 1
    compression = BI_RGB

    palette_bytes = b''
    ncolors = 0
    if bpp in (1, 2, 4, 8):
        if rng.random() < 0.5:
            ncolors = 1 << bpp
            palette_bytes = _make_palette_gray(ncolors)
        else:
            if bpp == 8:
                ncolors = rng.choice([16, 32, 64, 128, 256])
            else:
                ncolors = 1 << bpp
            palette_bytes = _make_palette_colorful(ncolors, rng)
    biClrUsed = ncolors if (bpp <= 8 and rng.random() < 0.7) else 0

    # Ensure final size <= 4096 by possibly shrinking height
    while _estimate_size(width, height_abs, bpp, ncolors) > 4096 and height_abs > 8:
        height_abs //= 2
    height = -height_abs if top_down else height_abs

    # Prepare row builders
    if bpp == 1:
        raw_stride = (width + 7) // 8
        row_builder = lambda: _row_packed_1bpp(width, rng)
    elif bpp == 2:
        raw_stride = (width + 3) // 4
        row_builder = lambda: _row_packed_nbpp(width, 2, rng)
    elif bpp == 4:
        raw_stride = (width + 1) // 2
        row_builder = lambda: _row_packed_nbpp(width, 4, rng)
    elif bpp == 8:
        raw_stride = width
        row_builder = lambda: _row_8bpp(width, rng)
    elif bpp == 16:
        raw_stride = width * 2
        row_builder = lambda: _row_16bpp_rgb565(width, rng)
    elif bpp == 24:
        raw_stride = width * 3
        row_builder = lambda: _row_24bpp(width, rng)
    elif bpp == 32:
        raw_stride = width * 4
        row_builder = lambda: _row_32bpp_xrgb(width, rng)
    else:
        raise ValueError("Unsupported bpp")

    stride = raw_stride + _pad4(raw_stride)
    pad = b'\x00' * (stride - raw_stride)

    rows: List[bytes] = []
    for _ in range(abs(height)):
        row = row_builder()
        if len(row) != raw_stride:
            row = row[:raw_stride] + b'\x00' * max(0, raw_stride - len(row))
        rows.append(row + pad)

    if height > 0:
        pixel_array = b''.join(reversed(rows))
    else:
        pixel_array = b''.join(rows)

    image_size = len(pixel_array)

    file_header_size = 14
    color_table_size = len(palette_bytes)
    bfOffBits = file_header_size + biSize + color_table_size

    dib = struct.pack(
        '<IIIHHIIIIII',
        biSize,
        width,
        (height & 0xFFFFFFFF),
        planes,
        bpp,
        compression,
        image_size,
        2835,
        2835,
        biClrUsed,
        0
    )

    bfType = b'BM'
    bfSize = file_header_size + len(dib) + color_table_size + image_size
    bfReserved1 = 0
    bfReserved2 = 0
    file_header = b''.join([
        bfType,
        struct.pack('<IHHI', bfSize, bfReserved1, bfReserved2, bfOffBits)
    ])

    bmp = file_header + dib + palette_bytes + pixel_array

    # Final guard: if still too large (shouldn't happen), truncate rows conservatively
    if len(bmp) > 4096:
        # Reduce to an 8x8 1bpp gray BMP deterministically
        rng2 = random.Random(seed ^ 0xA5A5A5A5)
        width2, height2, bpp2 = 8, 8, 1
        palette2 = _make_palette_gray(2)
        raw_stride2 = (width2 + 7) // 8
        stride2 = raw_stride2 + _pad4(raw_stride2)
        rows2 = []
        for _ in range(height2):
            rows2.append(_row_packed_1bpp(width2, rng2) + b'\x00' * _pad4(raw_stride2))
        pixel_array2 = b''.join(reversed(rows2))
        dib2 = struct.pack('<IIIHHIIIIII', 40, width2, height2, 1, bpp2, BI_RGB, len(pixel_array2), 2835, 2835, 2, 0)
        file_header2 = b'BM' + struct.pack('<IHHI', 14 + 40 + len(palette2) + len(pixel_array2), 0, 0, 14 + 40 + len(palette2))
        bmp = file_header2 + dib2 + palette2 + pixel_array2

    return bmp


def generate(seed: int) -> bytes:
    return _build_bmp(seed)
